<template><view class="page"><view class="eyebrow">人民日报精读</view><view class="page-title">深读一篇，学会一类</view><view class="section-head"><view class="section-title">已审核文章</view><view class="section-meta">{{ articles.length }} 篇</view></view><view v-if="loading" class="card state-card">正在加载精读内容…</view><view v-else-if="!articles.length" class="card state-card">暂时没有已发布文章</view><view v-for="article in articles" :key="article.id" class="card article-card" @tap="open(article.id)"><view class="article-meta">{{ article.source }} · {{ article.publishDate }}</view><view class="card-title">{{ article.title }}</view><view class="card-desc">{{ article.summary || '进入文章，完成精读与方法拆解' }}</view><view class="article-tags"><text v-for="tag in article.tags.slice(0,3)" :key="tag">{{ tag }}</text></view></view></view></template>
<script setup lang="ts">import { ref } from 'vue'; import Taro, { useDidShow } from '@tarojs/taro'; import { api, type RmrbArticle } from '@/api'; import { isLoggedIn } from '@/utils/auth'; import { showToast } from '@/utils/platform'; const articles=ref<RmrbArticle[]>([]); const loading=ref(false); function open(id:string){Taro.navigateTo({url:`/pages/reading/detail?id=${encodeURIComponent(id)}`})} async function load(){if(!isLoggedIn())return Taro.navigateTo({url:'/pages/auth/login'});loading.value=true;const response=await api.listArticles();loading.value=false;if(response.code===0&&response.data)articles.value=response.data;else showToast(response.message||'文章加载失败')} useDidShow(()=>void load())</script>
